                    "sql": "INSERT INTO snitch_db.maplemonk.offline_master_Daily_Report_1 (\"SKU_GROUP\", \"BRANCH_CODE\", \"MARKETPLACE_MAPPED\", \"FIRST_ORDER_DATE\", \"TOTAL_SALES\", \"TOTAL_RETURNS\", \"DAYS_SINCE_FIRST_ORDER\", \"AVERAGE_RETURN_SINCE_FIRST_ORDER\", \"NATURAL_ROS\", \"FINAL_ROS\", \"SALES_FIRST_7_DAYS\", \"SALES_FIRST_15_DAYS\", \"SALES_FIRST_30_DAYS\", \"SALES_LAST_7_DAYS\", \"SALES_LAST_15_DAYS\", \"SALES_LAST_30_DAYS\", \"INVENTORY\", \"XS_UNITS\", \"S_UNITS\", \"M_UNITS\", \"L_UNITS\", \"XL_UNITS\", \"XXL_UNITS\", \"XL3_UNITS\", \"XL4_UNITS\", \"XL5_UNITS\", \"XL6_UNITS\", \"NUM_SIZE_AVAILABLE\", \"FRESH_INVENTORY\", \"JIT_XS_UNITS\", \"JIT_S_UNITS\", \"JIT_M_UNITS\", \"JIT_L_UNITS\", \"JIT_XL_UNITS\", \"JIT_2XL_UNITS\", \"JIT_3XL_UNITS\", \"JIT_4XL_UNITS\", \"JIT_5XL_UNITS\", \"JIT_6XL_UNITS\", \"JIT_QTY\", \"CUT_SIZE_WITH_JIT_FLAG\", \"CUT_SIZE_FLAG\", \"DESIGNS\", \"NEW_CATEGORY\", \"COLLAR_NEW\", \"MATERIAL_NEW\", \"OCCASSION_NEW\", \"PRINT_DESIGN\", \"SLEEVE_TYPE\", \"FIT\", \"STYLE\", \"COLOR\", \"CUMULATIVE_SHARE\", \"PERCENTAGE_CATEGORY\", \"SKU_CLASS\", \"ONLINE_FINAL_ROS\", \"ONLINE_NATURAL_ROS\", \"CLUSTER\", \"BOH_AREA\", \"BASE_STOCK\", \"CARPET_AREA\", \"VM_OPTION\", \"DEPT_IDEAL\", \"AM\", \"RM\", \"NSM\", \"CITY\", \"STATE\", \"REGION\", \"PARTNER\", \"DATE\") SELECT \"SKU_GROUP\", \"BRANCH_CODE\", \"MARKETPLACE_MAPPED\", \"FIRST_ORDER_DATE\", \"TOTAL_SALES\", \"TOTAL_RETURNS\", \"DAYS_SINCE_FIRST_ORDER\", \"AVERAGE_RETURN_SINCE_FIRST_ORDER\", \"NATURAL_ROS\", \"FINAL_ROS\", \"SALES_FIRST_7_DAYS\", \"SALES_FIRST_15_DAYS\", \"SALES_FIRST_30_DAYS\", \"SALES_LAST_7_DAYS\", \"SALES_LAST_15_DAYS\", \"SALES_LAST_30_DAYS\", \"INVENTORY\", \"XS_UNITS\", \"S_UNITS\", \"M_UNITS\", \"L_UNITS\", \"XL_UNITS\", \"XXL_UNITS\", \"XL3_UNITS\", \"XL4_UNITS\", \"XL5_UNITS\", \"XL6_UNITS\", \"NUM_SIZE_AVAILABLE\", \"FRESH_INVENTORY\", \"JIT_XS_UNITS\", \"JIT_S_UNITS\", \"JIT_M_UNITS\", \"JIT_L_UNITS\", \"JIT_XL_UNITS\", \"JIT_2XL_UNITS\", \"JIT_3XL_UNITS\", \"JIT_4XL_UNITS\", \"JIT_5XL_UNITS\", \"JIT_6XL_UNITS\", \"JIT_QTY\", \"CUT_SIZE_WITH_JIT_FLAG\", \"CUT_SIZE_FLAG\", \"DESIGNS\", \"NEW_CATEGORY\", \"COLLAR_NEW\", \"MATERIAL_NEW\", \"OCCASSION_NEW\", \"PRINT_DESIGN\", \"SLEEVE_TYPE\", \"FIT\", \"STYLE\", \"COLOR\", \"CUMULATIVE_SHARE\", \"PERCENTAGE_CATEGORY\", \"SKU_CLASS\", \"ONLINE_FINAL_ROS\", \"ONLINE_NATURAL_ROS\", \"CLUSTER\", \"BOH_AREA\", \"BASE_STOCK\", \"CARPET_AREA\", \"VM_OPTION\", \"DEPT_IDEAL\", \"AM\", \"RM\", \"NSM\", \"CITY\", \"STATE\", \"REGION\", \"PARTNER\", current_date as date FROM snitch_db.maplemonk.offline_master where not exists ( SELECT 1 AS Exist FROM snitch_db.maplemonk.offline_master_Daily_Report_1 WHERE DATE = CURRENT_DATE() LIMIT 1) ; INSERT INTO SNITCH_DB.MAPLEMONK.OFFLINE_METAFIELD_IDEAL_MIX_V2_DAILY WITH category_mix AS ( SELECT TRIM(UPPER(STORE_CODE)) AS branch_code, UPPER(TRIM(category)) AS category, CAST(NULLIF(TRIM(CATEGORY_MIX), \'\') AS DECIMAL(10,4)) AS category_ideal_mix_pct FROM SNITCH_DB.MAPLEMONK.CATEGORY_MIX WHERE CATEGORY_MIX IS NOT NULL ), metafield_mix AS ( SELECT TRIM(UPPER(branch_code)) AS branch_code, TRIM(UPPER(style)) AS style, UPPER(TRIM(category_name)) AS category, CASE WHEN TRIM(UPPER(style)) = \'LUXE\' THEN \'0\' ELSE COALESCE(TRIM(UPPER(meta_1)), \'N/A\') END AS meta_1, CASE WHEN TRIM(UPPER(style)) = \'LUXE\' THEN \'0\' ELSE COALESCE(TRIM(UPPER(meta_2)), \'N/A\') END AS meta_2, CASE WHEN TRIM(UPPER(style)) = \'LUXE\' THEN \'0\' ELSE COALESCE(TRIM(UPPER(meta_3)), \'N/A\') END AS meta_3, CAST(NULLIF(TRIM(MIX), \'\') AS DECIMAL(10,4)) AS meta_mix_pct FROM ( SELECT *, \'T-SHIRTS\' AS category_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_T_SHIRTS_MIX UNION ALL SELECT *, \'SHIRTS\' AS category_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_SHIRTS_MIX UNION ALL SELECT *, \'TROUSERS\' AS category_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_TROUSERS_MIX UNION ALL SELECT *, \'JEANS\' AS category_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_JEANS_MIX ) ), meta_computed AS ( SELECT m.branch_code, m.style, m.category, m.meta_1, m.meta_2, m.meta_3, m.meta_mix_pct, c.category_ideal_mix_pct, ROUND(m.meta_mix_pct * c.category_ideal_mix_pct, 6) AS metafield_ideal_mix FROM metafield_mix m JOIN category_mix c ON m.branch_code = c.branch_code AND m.category = c.category WHERE m.meta_mix_pct > 0 ), fallback_general AS ( SELECT c.branch_code, \'SNITCH\' AS style, c.category, \'N/A\' AS meta_1, \'N/A\' AS meta_2, \'N/A\' AS meta_3, 1.0000 AS meta_mix_pct, c.category_ideal_mix_pct, c.category_ideal_mix_pct AS metafield_ideal_mix FROM category_mix c WHERE c.category NOT IN (\'T-SHIRTS\', \'SHIRTS\', \'TROUSERS\', \'JEANS\') AND c.category_ideal_mix_pct > 0 ) SELECT *, CURRENT_DATE AS snapshot_date FROM meta_computed UNION ALL SELECT *, CURRENT_DATE AS snapshot_date FROM fallback_general;",
                    "transaction": true
                }
            ) }}
